/* Deleting an account keeps what belongs to other people. A deleted buyer's orders were deleted with the account (orders.buyer_id cascaded off auth.users), and those orders are also the seller's sales records: orders.buyer_id may now be empty and the link to the account is cleared on delete instead of taking the order. creators.deleted_at marks a store whose owner deleted their account and was retired rather than wiped because buyers or money records hang off it (lib/account/delete-account): the store is closed, its products archived for sale and still in every buyer's library. public.account_deletions records every deletion: whose, removed or retired, who asked (the person, an admin, the spam purge, a business owner), when, and every step that failed, so a half finished deletion is seen and can be run again. Server only. Run after `63`. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'orders skipped: public.orders does not exist here'; RETURN; END IF; ALTER TABLE public.orders ALTER COLUMN buyer_id DROP NOT NULL; END $do$;
DO $do$ DECLARE c record; BEGIN IF to_regclass('public.orders') IS NULL THEN RETURN; END IF; FOR c IN SELECT con.conname FROM pg_constraint con JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey) WHERE con.conrelid = 'public.orders'::regclass AND con.contype = 'f' AND a.attname = 'buyer_id' AND con.confrelid = 'auth.users'::regclass AND con.confdeltype <> 'n' LOOP EXECUTE format('ALTER TABLE public.orders DROP CONSTRAINT %I', c.conname); END LOOP; IF NOT EXISTS (SELECT 1 FROM pg_constraint con JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey) WHERE con.conrelid = 'public.orders'::regclass AND con.contype = 'f' AND a.attname = 'buyer_id') THEN ALTER TABLE public.orders ADD CONSTRAINT orders_buyer_id_fkey FOREIGN KEY (buyer_id) REFERENCES auth.users (id) ON DELETE SET NULL NOT VALID; END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RETURN; END IF; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS deleted_at timestamptz; END $do$;
CREATE TABLE IF NOT EXISTS public.account_deletions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, creator_id uuid, mode text NOT NULL CHECK (mode IN ('removed', 'retired')), requested_by text NOT NULL CHECK (requested_by IN ('self', 'admin', 'spam_purge', 'business_owner')), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, failures jsonb NOT NULL DEFAULT '[]'::jsonb);
CREATE INDEX IF NOT EXISTS account_deletions_user_idx ON public.account_deletions (user_id, started_at DESC);
CREATE INDEX IF NOT EXISTS account_deletions_failed_idx ON public.account_deletions (started_at DESC) WHERE jsonb_array_length(failures) > 0;
ALTER TABLE public.account_deletions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.account_deletions FROM anon, authenticated;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
notify pgrst, 'reload schema';
